responseFormat.typescriptTypesReference:
type Citation = {
commentId: number;
};

type Clause = {
text: string;
citations: Citation[];
};

type Sentence = {
clauses: Clause[];
};

type Paragraph = {
id: string; // e.g. "consensus_overview"
title: string;
sentences: Sentence[];
};

type Subtask = {
id: string;
title: string;
paragraphs: Paragraph[];
};

polisAnalysisPrompt.example:
{
"id": "group_informed_consensus",
"title": "Areas of Cross-Tribe Consensus",
"paragraphs": [
{
"id": "consensus_overview",
"title": "Overview of Cross-Tribe Consensus",
"sentences": [
{
"clauses": [
{
"text": "Participants found significant common ground across different tribes, with strong agreement on several statements that cut across the usual divisions.",
"citations": [12, 15, 23]
}
]
}
]
},
{
"id": "environmental_protection",
"title": "Consensus on Environmental Protection",
"sentences": [
{
"clauses": [
{
"text": "The strongest area of cross-tribe agreement centered on environmental protection, with statements supporting conservation efforts receiving high approval from all tribes.",
"citations": [25, 31, 45]
},
{
"text": "This shared commitment to environmental stewardship transcended otherwise significant divisions on economic policy and regulatory approaches.",
"citations": [52, 54, 61]
}
]
}
]
}
]
}
